end
end)
hit.MouseLeave:Connect(function()
if not style.Face then
Motion.Spring(face, "BackgroundTransparency", 1, "Fast")
else
Motion.Spring(face, "BackgroundColor3", Theme.Colors[style.Face] or Color3.new(1, 1, 1), "Fast")
end
