function Draw.Thumb(parent, image, tint, size, position)
local tile = Draw.Box("ImageLabel", {
Name = "Thumb",
Image = image or "",
ScaleType = Enum.ScaleType.Fit,
AnchorPoint = Vector2.new(0, 0.5),
Position = position or UDim2.new(0, 4, 0.5, 0),
