highlight.Enabled = self.Visible
billboard.Enabled = self.Visible and self.TextOn ~= false
if self.Tracer then self.Tracer.Visible = self.Visible end
end
function instance:Remove()
if self.Destroyed then return end
self.Destroyed = true
